#include "umicom/studio/frontend_studio_preview.h"
static UmiFrontendStudio *service(UmiStudioWebPlatform *p){return umi_studio_web_platform_frontend_studio(p);}
UmiStatus umi_studio_frontend_preview_start(UmiStudioWebPlatform *p){UmiFrontendStudio *s=service(p);UmiStatus st;if(s==NULL)return UMI_STATUS_INVALID_ARGUMENT;st=umi_frontend_dev_server_start(&s->server);if(st==UMI_STATUS_OK){st=umi_frontend_preview_session_navigate(&s->preview,s->server.base_url);s->revision+=1U;}return st;}
UmiStatus umi_studio_frontend_preview_stop(UmiStudioWebPlatform *p){UmiFrontendStudio *s=service(p);UmiStatus st;if(s==NULL)return UMI_STATUS_INVALID_ARGUMENT;st=umi_frontend_dev_server_stop(&s->server);if(st==UMI_STATUS_OK){s->preview.connected=0;s->preview.revision+=1U;s->revision+=1U;}return st;}
UmiStatus umi_studio_frontend_preview_navigate(UmiStudioWebPlatform *p,const char *url){UmiFrontendStudio *s=service(p);UmiStatus st;if(s==NULL)return UMI_STATUS_INVALID_ARGUMENT;st=umi_frontend_preview_session_navigate(&s->preview,url);if(st==UMI_STATUS_OK)s->revision+=1U;return st;}
UmiStatus umi_studio_frontend_preview_select_device(UmiStudioWebPlatform *p,const char *id){UmiFrontendStudio *s=service(p);UmiFrontendDevicePreset d;UmiStatus st;if(s==NULL)return UMI_STATUS_INVALID_ARGUMENT;st=umi_frontend_device_registry_find(&s->devices,id,&d);if(st==UMI_STATUS_OK)st=umi_frontend_preview_session_set_device(&s->preview,&d);if(st==UMI_STATUS_OK)s->revision+=1U;return st;}
UmiStatus umi_studio_frontend_preview_reload(UmiStudioWebPlatform *p){UmiFrontendStudio *s=service(p);UmiStatus st;if(s==NULL)return UMI_STATUS_INVALID_ARGUMENT;st=umi_frontend_preview_session_reload(&s->preview);if(st==UMI_STATUS_OK)s->revision+=1U;return st;}
